import sys

class NumberTheory:
    class Mod998:
        def __init__(self):
            self.mod = 998

        def add(self, a, b):
            return (a + b) % self.mod

        def mult(self, *args):
            result = 1
            for num in args:
                result = (result * num) % self.mod
            return result

        def smallInv(self, a):
            # Fermat's little theorem for prime mod
            return pow(a, self.mod - 2, self.mod)

        def div(self, a, b):
            return self.mult(a, self.smallInv(b))

        def paritySign(self, k):
            # returns 1 if k is odd, -1 if even
            return 1 if k % 2 == 1 else -1

        def ncr(self, n, r):
            if r > n or r < 0:
                return 0
            numerator = 1
            denominator = 1
            for i in range(r):
                numerator = (numerator * (n - i)) % self.mod
                denominator = (denominator * (i + 1)) % self.mod
            return self.div(numerator, denominator)

def compute_shuffles():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])

    mod = NumberTheory.Mod998()
    mod.fInv = lambda x: pow(x, mod.mod - 2, mod.mod)  # define fInv as modular inverse
    # Since in Java code, mod.fInv(n + m) is called but not stored, assuming it's for some side effect.
    # In Python, we just call it to match behavior.
    mod.fInv(n + m)

    phaseSize = 1
    p = 1
    i = 0
    while p != 0:
        p = (p * (n - i)) % mod.mod
        inv = mod.fInv(n + m - i)
        p = (p * inv) % mod.mod
        phaseSize = (phaseSize + p) % mod.mod
        i += 1

    answer = 0
    for k in range(1, n + 1):
        sign = 1 if (k + 1) % 2 == 1 else -1
        numPhases = (m + k) * mod.fInv(k) % mod.mod
        term = (sign * mod.ncr(n, k)) % mod.mod
        term = (term * numPhases) % mod.mod
        term = (term * phaseSize) % mod.mod
        answer = (answer + term) % mod.mod

    print(answer)

compute_shuffles()

